Review this Go event dispatcher and fix any issues:

```go
type Event struct {
    Type    string
    Payload any
}

func Dispatch(e Event) error {
    switch e.Type {
    case "user.created":
        payload := e.Payload.(*UserCreated)
        return handleUserCreated(payload)
    case "order.placed":
        payload := e.Payload.(*OrderPlaced)
        return handleOrderPlaced(payload)
    case "payment.failed":
        payload := e.Payload.(*PaymentFailed)
        return handlePaymentFailed(payload)
    default:
        return fmt.Errorf("unknown event type: %s", e.Type)
    }
}
```

